def document(x,y,label):return f'<g transform="translate({x} {y})"><rect width="220" height="230" rx="8" fill="#fffaf0" stroke="{G}" stroke-width="4"/>{text(20,40,label,21)}'+''.join(f'<path d="M22 {k} H193" stroke="#b9c5b4" stroke-width="5"/>' for k in range(70,210,27))+'</g>'
def wrap(name,title,inner):
 s=f'<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="760" viewBox="0 0 1200 760" role="img" aria-label="{html.escape(title)}"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#dae8df"/><stop offset="1" stop-color="#faf2dc"/></linearGradient></defs><rect width="1200" height="760" rx="22" fill="#f5efdf"/><rect x="24" y="24" width="1152" height="650" rx="18" fill="url(#sky)"/>{text(58,83,title,34)}{inner}<path d="M50 692 H1150" stroke="#c8b88d"/>{text(55,732,'ILUSTRASI PENDIDIKAN • Bukan foto sejarah',20,'#796842')}</svg>'
 (OUT/(name+'.svg')).write_text(s)
