def visual(key,title,caption,explanation,period='Situasi rekaan masa kini'):
 return dict(id=key,path=f'assets/visuals/{key}.svg',title=title,caption=caption,alt=caption,kind='Ilustrasi pendidikan',date=period,creator='Misi Rukun Negara',license='CC BY 4.0',sourceUrl=BOOK,sourceTitle='Rujukan isi: Buku Teks Sejarah Tahun 6, hlm. 36–46',explanation=explanation,audio='')
v={}
def add(a,*items):v[a]=list(items)
add('ekonomi',visual('ekonomi','Tiga kegiatan ekonomi','Hasil tani, bijih timah dan getah.','Perhatikan hasil dan tempat kerja yang berbeza. Kegiatan ekonomi yang terpisah mengehadkan hubungan masyarakat.','Gambaran konsep ekonomi dahulu; bukan foto 1969'),dict(id='tin-archive',path='assets/visuals/tin-archive.jpg',title='Perlombongan bijih timah di Malaya',caption='Pam kerikil dalam foto arkib. Tarikh rakaman tidak dinyatakan; bukan bukti foto 1969.',alt='Kawasan perlombongan bijih timah dengan pam kerikil dalam foto hitam putih.',kind='Foto sejarah',date='Tarikh rakaman tidak dinyatakan',creator='The National Archives UK, CO 1069/493/21',license='No known copyright restrictions — Flickr Commons',sourceUrl='https://www.flickr.com/photos/nationalarchives/7888162576/',sourceTitle='The National Archives UK • CO 1069/493/21',explanation='Foto ini menunjukkan satu cara perlombongan bijih timah. Bandingkan dengan pertanian dan perladangan getah.',audio=''),dict(id='rubber-archive',path='assets/visuals/rubber-archive.webp',title='Menoreh getah, sekitar 1910',caption='Foto awal kegiatan menoreh getah. Diambil sekitar 1910, bukan pada 1969.',alt='Seorang penoreh berdiri di sisi pokok getah yang ditoreh.',kind='Foto sejarah',date='Sekitar 1910',creator='C. J. Kleingrothe • Koleksi KITLV, Leiden University Libraries, 79940',license='Public domain • karya terbit sebelum 1931; pengarang meninggal pada 1942',sourceUrl='https://commons.wikimedia.org/wiki/File:KITLV_-_79940_-_Kleingrothe,_C.J._-_Medan_-_Tapping_of_a_23-year-old_rubber_tree_on_a_plantation_in_Malaysia_-_circa_1910.tif',sourceTitle='KITLV 79940 • Leiden University Libraries / Wikimedia Commons',explanation='Perhatikan torehan pada batang pokok dan bekas pengumpulan. Foto ini membantu mengenal kegiatan perladangan getah, bukan merakam tahun 1969.',audio=''))
add('penempatan',visual('penempatan','Kampung, bandar dan ladang','Rajah perbandingan tempat tinggal; bukan peta sebenar.','Tempat tinggal yang terpisah mengurangkan peluang berinteraksi. Rajah ini tidak menetapkan pekerjaan atau tempat tinggal semua orang mengikut kaum.','Rajah konsep masyarakat dahulu; bukan peta 1969'))
add('politik',visual('politik','Fahaman politik berbeza','Rajah konsep yang tidak mewakili mana-mana parti.','Perbezaan fahaman politik boleh merenggangkan hubungan. Keperluan memperkukuh perpaduan menjadi latar pengenalan Rukun Negara.','Rajah konsep; bukan bahan kempen sebenar'),visual('latar','13 Mei, MAGERAN dan Rukun Negara','Garis masa pendidikan tanpa visual keganasan. MAGERAN ialah Majlis Gerakan Negara.','Peristiwa 13 Mei 1969 menjadi latar penting. MAGERAN berusaha memulihkan keamanan. Rukun Negara diisytiharkan pada 31 Ogos 1970.','Latar 1969–1970; rajah diterbitkan untuk pembelajaran'))
