v['matlamat'][0]['sourceUrl']=ARKIB;v['matlamat'][0]['sourceTitle']='Arkib Negara Malaysia • Rukun Negara'
for key,title,expl in [('perpaduan','Perpaduan lebih erat','Kerjasama merapatkan hubungan seluruh masyarakat.'),('demokrasi','Cara hidup demokratik','Perbincangan dan penyertaan membantu membuat keputusan bersama.'),('adil','Masyarakat adil','Kemakmuran perlu dinikmati bersama secara adil dan saksama.'),('budaya','Sikap liberal terhadap tradisi kebudayaan','Kita menerima dan menghormati tradisi kebudayaan yang pelbagai.'),('sains','Masyarakat progresif','Sains dan teknologi moden membantu kemajuan masyarakat.')]:v['matlamat'].append(visual(key,title,expl,expl,'Contoh konsep; bukan foto majlis 1970'))
for a,key,title,expl in [('tuhan','agama','Kepercayaan kepada Tuhan','Agama menjadi pegangan utama. Hormati amalan agama dan kepercayaan.'),('raja','raja','Kesetiaan kepada Raja dan Negara','Yang di-Pertuan Agong ialah Ketua Utama Negara. Rakyat memberikan taat setia kepada Raja dan negara.'),('perlembagaan','perlembagaan','Keluhuran Perlembagaan','Perlembagaan Persekutuan ialah undang-undang tertinggi negara.'),('undang','undang','Kedaulatan Undang-undang','Undang-undang dipatuhi untuk menjaga keselamatan dan keamanan.'),('sopan','sopan','Kesopanan dan Kesusilaan','Amalan nilai murni mencerminkan keperibadian rakyat Malaysia.'),('agama','agama','Meraikan kepelbagaian agama','Memberi ruang dan menjaga ketenangan menunjukkan hormat kepada kepercayaan jiran.'),('patriotik','patriotik','Masyarakat patriotik','Cinta akan negara ditunjukkan melalui hormat dan sumbangan kepada masyarakat.'),('patuh','patuh','Menghormati undang-undang','Menjaga kemudahan awam dan menolak vandalisme membantu keamanan masyarakat.'),('perpaduan','perpaduan','Mengukuhkan perpaduan','Masyarakat berbilang kaum bekerjasama dan membahagikan tugas dengan adil.'),('nilai','nilai','Menerapkan nilai murni','Bantuan yang sopan dan ikhlas menunjukkan nilai murni.'),('jati','jati','Membentuk jati diri','Kejujuran, toleransi dan kerjasama membentuk peribadi yang baik.')]:add(a,visual(key,title,expl,expl))
