# Observation asks students to interpret what is actually shown, before the existing assessment.
obs={
'ekonomi':('Apakah perbezaan yang kamu lihat?',['Hasil dan tempat kerja berbeza.','Semua menghasilkan bijih timah.','Semua bekerja di bandar.'],0,'Hasil tani, bijih timah dan getah datang daripada kegiatan ekonomi berbeza.'),
'penempatan':('Apakah kesan tempat tinggal berjauhan?',['Interaksi pasti lebih kerap.','Peluang berinteraksi berkurang.','Semua masyarakat sama.'],1,'Jarak mengurangkan peluang berinteraksi, bukan menentukan sifat sesuatu kaum.'),
'politik':('Mengapa pandangan berbeza perlu diurus dengan baik?',['Supaya semua pandangan dihapuskan.','Supaya satu kaum dipersalahkan.','Supaya hubungan tidak renggang.'],2,'Perbezaan fahaman politik boleh merenggangkan hubungan. Kita perlu memperkukuh perpaduan.'),
'sebab':('Apakah hubungan tiga petunjuk ini?',['Ketiga-tiganya sebab pengenalan Rukun Negara.','Ketiga-tiganya nama prinsip.','Ketiga-tiganya tarikh pengisytiharan.'],0,'Ekonomi, tempat tinggal dan fahaman politik ialah tiga sebab. Peristiwa 13 Mei ialah latar sejarah.'),
'matlamat':('Gambar perbincangan dan pilihan bersama menunjukkan matlamat apa?',['Kemajuan sains sahaja.','Cara hidup demokratik.','Pengasingan tempat tinggal.'],1,'Penyertaan dan keputusan bersama membantu menerangkan cara hidup demokratik.'),
 'tuhan':('Mengapa ruang ibadat dijaga tenang?',['Supaya agama orang lain dihalang.','Supaya semua mesti beragama sama.','Supaya amalan agama dihormati.'],2,'Menghormati amalan agama menunjukkan Kepercayaan kepada Tuhan.'),
'raja':('Apakah institusi yang dirujuk oleh simbol ini?',['Institusi Raja.','Sebuah parti politik.','Ketua kelas.'],0,'Rajah ini menunjukkan peranan Yang di-Pertuan Agong sebagai Ketua Utama Negara.'),
'perlembagaan':('Mengapa dokumen ini menjadi panduan negara?',['Ia menggantikan semua prinsip.','Ia undang-undang tertinggi negara.','Ia hanya peraturan sebuah kelas.'],1,'Perlembagaan Persekutuan ialah undang-undang tertinggi negara.'),
'undang':('Mengapa murid berhenti sebelum melintas?',['Untuk melambatkan orang lain.','Untuk mengelakkan perbincangan.','Untuk mematuhi aturan keselamatan.'],2,'Mematuhi aturan melindungi diri dan orang lain.'),
'sopan':('Apakah amalan yang ditunjukkan?',['Mendengar dan mengucapkan terima kasih.','Membuat keputusan melalui undian.','Menoreh pokok getah.'],0,'Mendengar dengan tertib dan berterima kasih ialah amalan kesopanan.'),
'agama':('Peranan apakah yang berkaitan dengan situasi ini?',['Menggantikan kepercayaan jiran.','Meraikan kepelbagaian agama dan kepercayaan.','Memilih kegiatan ekonomi.'],1,'Menghormati keperluan ibadat membantu kehidupan harmoni.'),
'patriotik':('Apakah makna menyumbang dalam sambutan kebangsaan?',['Hanya mahu mendapat hadiah.','Hanya mengikut warna pakaian.','Menunjukkan cinta akan negara.'],2,'Patriotisme merangkumi rasa cinta dan tanggungjawab kepada negara.'),
'patuh':('Mengapa bangku awam perlu dijaga?',['Undang-undang melindungi kemudahan bersama.','Bangku hanya milik seorang murid.','Menjaganya ialah kegiatan perlombongan.'],0,'Mematuhi undang-undang membantu menjaga hak dan keselamatan masyarakat.'),
'perpaduan':('Apakah bukti kerjasama dalam gambar?',['Semua hanya melihat.','Tugas dikongsi antara jiran.','Setiap orang perlu menjauh.'],1,'Pembahagian tugas membolehkan jiran berbilang latar bekerjasama.'),
'nilai':('Apakah yang patut dilakukan sebelum membantu?',['Mengambil barang tanpa izin.','Menunggu untuk dipuji.','Meminta izin dengan sopan.'],2,'Bantuan yang menghormati orang lain menunjukkan nilai murni.'),
'jati':('Apakah nilai pada dokumen hasil sendiri?',['Integriti.','Pengasingan.','Perbezaan ekonomi.'],0,'Menyiapkan hasil sendiri menunjukkan kejujuran dan membentuk jati diri.'),
}
