cpath.write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n')
Path('docs/visual-sources.json').write_text(json.dumps(dict(checked='2026-11-08',notes=['No textbook pages are reproduced.','Original diagrams are teaching illustrations, not archival evidence.','Archival dates are not replaced with 1969.','No graphic violence or fabricated political campaign materials.','The two example image proxy URLs were visual references, not licence evidence.'],images=[item for items in v.values() for item in items]),ensure_ascii=False,indent=2)+'\n')
